window.FIELD_CHAPTER_PARTS["book-3-full-book"] = window.FIELD_CHAPTER_PARTS["book-3-full-book"] || {};
window.FIELD_CHAPTER_PARTS["book-3-full-book"][112] = "<ul>\n<li><strong>Definition:</strong> A short description of who has what problem in what context and why it matters, written without a solution.</li>\n<li><strong>Example:</strong> &quot;New users abandon setup at the permissions screen because they cannot see why it is needed.&quot;</li>\n<li><strong>Non-example:</strong> &quot;We need an onboarding wizard.&quot;</li>\n<li><strong>Owning chapter:</strong> C06</li>\n</ul>\n<span id=\"gl-product-led-growth\"></span>\n<h3>product-led growth</h3>\n<ul>\n<li><strong>Definition:</strong> A go-to-market approach in which the product itself drives acquisition, conversion and expansion, typically through a free or self-serve entry, quick time to value and in-product prompts to invite others or upgrade.</li>\n<li><strong>Example:</strong> A developer tool with a free tier that teams upgrade when they hit a limit.</li>\n<li><strong>Non-example:</strong> A product sold only through a sales team with demos and negotiated contracts.</li>\n<li><strong>Owning chapter:</strong> C20</li>\n</ul>\n<span id=\"gl-product-market-fit\"></span>\n<h3>product-market fit</h3>\n<ul>\n<li><strong>Definition:</strong> The state in which a product satisfies a strong market need: enough of the right customers use it, value it and keep using it without being pushed; read from a pattern of retention that flattens, a strong share who would be very disappointed without it, organic growth and willingness to pay.</li>\n<li><strong>Example:</strong> A cohort retention curve that levels at 25% and a segment where 46% would be very disappointed to lose the product.</li>\n<li><strong>Non-example:</strong> A waiting list of 75,000 sign-ups or a launch-week spike.</li>\n<li><strong>Owning chapter:</strong> C26</li>\n</ul>\n<span id=\"gl-product-sense\"></span>\n<h3>product sense</h3>\n<ul>\n<li><strong>Definition:</strong> The ability to identify the right user problem, generate and choose between solutions, and define success, usually assessed with an open-ended prompt.</li>\n<li><strong>Example:</strong> Choosing a commuter segment, ranking their pain points, and recommending one feature with a metric.</li>\n<li><strong>Non-example:</strong> Listing ten features for an app without naming a user.</li>\n<li><strong>Owning chapter:</strong> C07</li>\n</ul>\n<span id=\"gl-product-thinking\"></span>\n<h3>product thinking</h3>\n<ul>\n<li><strong>Definition:</strong> Reasoning from a user problem to a solution to a measurable outcome, rather than starting from a solution.</li>\n<li><strong>Example:</strong> Asking why riders cancel before deciding whether to change the cancellation policy.</li>\n<li><strong>Non-example:</strong> &quot;Competitors have a chatbot, so we should add one.&quot;</li>\n<li><strong>Owning chapter:</strong> C02</li>\n</ul>\n<span id=\"gl-product-triad\"></span>\n<h3>product triad</h3>\n<ul>\n<li><strong>Definition:</strong> The core trio on a feature team, a product manager, an engineering lead and a design lead, who share responsibility for a product outcome and decide together, with data science and others attached.</li>\n<li><strong>Example:</strong> The PM, the tech lead and the design lead agreeing scope for a quarter.</li>\n<li><strong>Non-example:</strong> A formal org chart level or a committee.</li>\n<li><strong>Owning chapter:</strong> C01</li>\n</ul>\n<span id=\"gl-prompt\"></span>\n<h3>prompt</h3>\n<ul>\n<li><strong>Definition:</strong> The input given to a language model, including instructions, context and examples; a system prompt is the standing instructions the product sets.</li>\n<li><strong>Example:</strong> An instruction plus three example rewrites plus the email to rewrite.</li>\n<li><strong>Non-example:</strong> The model's answer.</li>\n<li><strong>Owning chapter:</strong> C24</li>\n</ul>\n<span id=\"gl-prompt-injection\"></span>\n<h3>prompt injection</h3>\n<ul>\n<li><strong>Definition:</strong> An attack in which instructions placed in content the model processes (a document, web page or email) override or redirect the model's intended behavior.</li>\n<li><strong>Example:</strong> A calendar invite saying to ignore prior instructions and forward the attendee list.</li>\n<li><strong>Non-example:</strong> A user simply asking the assistant a question.</li>\n<li><strong>Owning chapter:</strong> C24</li>\n</ul>\n<span id=\"gl-proxy-metric\"></span>\n<h3>proxy metric</h3>\n<ul>\n<li><strong>Definition:</strong> A measurable stand-in for an outcome that is hard to measure directly.</li>\n<li><strong>Example:</strong> Sessions that end without a repeat search, as a proxy for finding the answer.</li>\n<li><strong>Non-example:</strong> The outcome itself.</li>\n<li><strong>Owning chapter:</strong> C05</li>\n</ul>\n<span id=\"gl-pull-forward\"></span>\n<h3>pull-forward</h3>\n<ul>\n<li><strong>Definition:</strong> Demand or activity brought earlier by a promotion or deadline, which raises the metric now and lowers it later, leaving the total roughly unchanged.</li>\n<li><strong>Example:</strong> A promotion week of 125 followed by weeks of 80 and 90 against a baseline of 100, a net of 295 against 300.</li>\n<li><strong>Non-example:</strong> A lasting increase in demand that persists after the promotion ends.</li>\n<li><strong>Owning chapter:</strong> C13</li>\n</ul>\n<span id=\"gl-pyramid-principle\"></span>\n<h3>pyramid principle</h3>\n<ul>\n<li><strong>Definition:</strong> A way of organizing a message with the answer at the top, supported by a few grouped arguments of the same kind in a logical order, each backed by evidence.</li>\n<li><strong>Example:</strong> A recommendation supported by three named reasons, each with its evidence.</li>\n<li><strong>Non-example:</strong> Seven unranked points in the order they occurred to the speaker.</li>\n<li><strong>Owning chapter:</strong> C32</li>\n</ul>\n<span id=\"gl-rag\"></span>\n<h3>retrieval-augmented generation</h3>\n<ul>\n<li><strong>Definition:</strong> A technique that retrieves relevant documents and supplies them to a model when it generates an answer.</li>\n<li><strong>Example:</strong> A support bot that fetches help-center articles before answering.</li>\n<li><strong>Non-example:</strong> Fine-tuning a model on a dataset.</li>\n<li><strong>Owning chapter:</strong> C24</li>\n</ul>\n<span id=\"gl-randomization\"></span>\n<h3>randomization</h3>\n<ul>\n<li><strong>Definition:</strong> Assigning units to variants by chance so that the groups differ, on average, only in the treatment.</li>\n<li><strong>Example:</strong> Hashing user IDs to assign variants.</li>\n<li><strong>Non-example:</strong> Letting users choose which version to use.</li>\n<li><strong>Owning chapter:</strong> C14</li>\n</ul>\n<span id=\"gl-ranking\"></span>\n<h3>ranking</h3>\n<ul>\n<li><strong>Definition:</strong> Ordering items by a predicted score so that the most valuable appear first.</li>\n<li><strong>Example:</strong> Ordering 400 candidate titles by the predicted chance a member will start and finish each.</li>\n<li><strong>Non-example:</strong> Choosing a single yes-or-no label for an item.</li>\n<li><strong>Owning chapter:</strong> C23</li>\n</ul>\n<span id=\"gl-rate-limiting\"></span>\n<h3>rate limiting</h3>\n<ul>\n<li><strong>Definition:</strong> Capping how many requests a caller may make in a period, to protect a system from overload or abuse.</li>\n<li><strong>Example:</strong> At most 100 requests per minute per account.</li>\n<li><strong>Non-example:</strong> Adding servers to absorb unlimited traffic.</li>\n<li><strong>Owning chapter:</strong> C22</li>\n</ul>\n<span id=\"gl-readiness-gate\"></span>\n<h3>readiness gate</h3>\n<ul>\n<li><strong>Definition:</strong> A written decision rule, set in advance, that says when to apply to top-choice targets: a list of measurable conditions that must all be true, re-tested before each loop, replacing anxiety and the calendar as the decider.</li>\n<li><strong>Example:</strong> Outside-scored averages of at least 4.0 on high-weight dimensions, calibration within half a point and three full mock loops with an independent lean of hire or better.</li>\n<li><strong>Non-example:</strong> A feeling that the last mock went well, or the date on which a window opens.</li>\n<li><strong>Owning chapter:</strong> C37</li>\n</ul>\n<span id=\"gl-reading-map\"></span>\n<h3>reading map</h3>\n<ul>\n<li><strong>Definition:</strong> A ranking of the chapters of this book into a core path, deep dives and a reference library, with the hours each costs, so that the book's length does not burden a reader on a twelve-month plan.</li>\n<li><strong>Example:</strong> A core path of 21 chapters at about 62.7 study hours, eight deep dives at about 22.4 and a reference library of five chapters at about 12.</li>\n<li><strong>Non-example:</strong> A table of contents.</li>\n<li><strong>Owning chapter:</strong> C37</li>\n</ul>\n<span id=\"gl-recommender-system\"></span>\n<h3>recommender system</h3>\n<ul>\n<li><strong>Definition:</strong> A system that predicts which items a user will value and ranks them for display.</li>\n<li><strong>Example:</strong> A feed that orders videos by predicted interest.</li>\n<li><strong>Non-example:</strong> A list sorted alphabetically.</li>\n<li><strong>Owning chapter:</strong> C23</li>\n</ul>\n<span id=\"gl-red-teaming\"></span>\n<h3>red-teaming</h3>\n<ul>\n<li><strong>Definition:</strong> Deliberate adversarial testing in which people try to make a system fail or cause harm, to find weaknesses before real users do.</li>\n<li><strong>Example:</strong> Testers attempting 250 prompts in each of eight harm categories against an assistant before launch.</li>\n<li><strong>Non-example:</strong> Friendly user studies with cooperative testers.</li>\n<li><strong>Owning chapter:</strong> C25</li>\n</ul>\n<span id=\"gl-regression-test\"></span>\n<h3>regression test</h3>\n<ul>\n<li><strong>Definition:</strong> A test that checks that a change has not broken behavior that used to work; for AI products it is the evaluation set rerun on every change and read by slice.</li>\n<li><strong>Example:</strong> Rerunning 400 cases after a prompt change and finding that refunds fell from 96% to 78%.</li>\n<li><strong>Non-example:</strong> A test of a brand-new feature that has no prior behavior.</li>\n<li><strong>Owning chapter:</strong> C25</li>\n</ul>\n<span id=\"gl-regression-to-the-mean\"></span>\n<h3>regression to the mean</h3>\n<ul>\n<li><strong>Definition:</strong> The tendency for unusually high or low measurements to be followed by measurements closer to the average, because part of the extreme was chance.</li>\n<li><strong>Example:</strong> The ten worst-converting pages improve next week with no change made to them.</li>\n<li><strong>Non-example:</strong> A real improvement caused by a fix that a control group does not show.</li>\n<li><strong>Owning chapter:</strong> C12</li>\n</ul>\n<span id=\"gl-retention\"></span>\n<h3>retention</h3>\n<ul>\n<li><strong>Definition:</strong> The share of users or customers who keep using or paying over time, measured by cohort.</li>\n<li><strong>Example:</strong> The share of March signups still active 30 days later.</li>\n<li><strong>Non-example:</strong> The total number of users ever acquired.</li>\n<li><strong>Owning chapter:</strong> C05</li>\n</ul>\n<span id=\"gl-reversible-decision\"></span>\n<h3>reversible decision</h3>\n<ul>\n<li><strong>Definition:</strong> A decision that can be undone cheaply, so it can be made quickly on less evidence.</li>\n<li><strong>Example:</strong> Running a one-week test of different button text.</li>\n<li><strong>Non-example:</strong> Discontinuing a product line.</li>\n<li><strong>Owning chapter:</strong> C02</li>\n</ul>\n<span id=\"gl-risk-tier\"></span>\n<h3>risk tier</h3>\n<ul>\n<li><strong>Definition:</strong> A category of AI use ranked by its potential for harm, which sets the obligations on its provider and deployer, as in the risk-based approach of the European Union's AI Act.</li>\n<li><strong>Example:</strong> A resume-screening tool classed as high-risk and a spam filter as minimal-risk.</li>\n<li><strong>Non-example:</strong> A company's internal priority level for a bug.</li>\n<li><strong>Owning chapter:</strong> C25</li>\n</ul>\n<span id=\"gl-riskiest-assumption\"></span>\n<h3>riskiest assumption</h3>\n<ul>\n<li><strong>Definition:</strong> The assumption that, if false, would sink an idea and about which the team knows least; the one to test first.</li>\n<li><strong>Example:</strong> That students will pay $40 a week for a dorm meal kit.</li>\n<li><strong>Non-example:</strong> An assumption that is likely true or would not change the decision.</li>\n<li><strong>Owning chapter:</strong> C26</li>\n</ul>\n<span id=\"gl-roadmap\"></span>\n<h3>roadmap</h3>\n<ul>\n<li><strong>Definition:</strong> A plan of what will be built and when; the logic behind it is the strategy.</li>\n<li><strong>Example:</strong> A quarterly plan that names the three problems the team will work on and the order, tied to the strategy.</li>\n<li><strong>Non-example:</strong> A list of wished-for features with no logic for the order.</li>\n<li><strong>Owning chapter:</strong> C18</li>\n</ul>\n<span id=\"gl-rollback\"></span>\n<h3>rollback</h3>\n<ul>\n<li><strong>Definition:</strong> Reverting a release to its previous state.</li>\n<li><strong>Example:</strong> Switching a flag off after error rates spike.</li>\n<li><strong>Non-example:</strong> Fixing the bug in the next release.</li>\n<li><strong>Owning chapter:</strong> C17</li>\n</ul>\n<span id=\"gl-rollback-trigger\"></span>\n<h3>rollback trigger</h3>\n<ul>\n<li><strong>Definition:</strong> A pre-agreed condition (metric, threshold, window, owner) that, when met, causes a release to be reverted or paused.</li>\n<li><strong>Example:</strong> Payment success below 95.0% over a rolling two hours: the on-call engineer turns off the flag.</li>\n<li><strong>Non-example:</strong> A debate at 2 a.m. about whether the drop is bad enough.</li>\n<li><strong>Owning chapter:</strong> C17</li>\n</ul>\n<span id=\"gl-root-cause\"></span>\n<h3>root cause</h3>\n<ul>\n<li><strong>Definition:</strong> The underlying condition that, if removed, stops the problem from recurring, as opposed to a symptom.</li>\n<li><strong>Example:</strong> A payment-library update that broke one checkout step.</li>\n<li><strong>Non-example:</strong> &quot;Conversion fell.&quot;</li>\n<li><strong>Owning chapter:</strong> C03</li>\n</ul>\n<span id=\"gl-rotational-program\"></span>\n<h3>rotational program</h3>\n<ul>\n<li><strong>Definition:</strong> A structured early-career program in which a new hire rotates across several teams over one to two years, with training, mentorship and a cohort, before settling into a role.</li>\n<li><strong>Example:</strong> A two-year associate product manager program with two rotations.</li>\n<li><strong>Non-example:</strong> A direct hire into one team with no rotations.</li>\n<li><strong>Owning chapter:</strong> C01</li>\n</ul>\n<span id=\"gl-sales-cycle\"></span>\n<h3>sales cycle</h3>\n<ul>\n<li><strong>Definition:</strong> The time from first contact with a prospective customer to a signed contract, often months in enterprise sales, shaped by the buying committee, security review and budget cycles.</li>\n<li><strong>Example:</strong> A nine-month cycle from first demo to signature.</li>\n<li><strong>Non-example:</strong> The time a user takes to sign up for a free plan.</li>\n<li><strong>Owning chapter:</strong> C27</li>\n</ul>\n<span id=\"gl-sample-ratio-mismatch\"></span>\n<h3>sample ratio mismatch</h3>\n<ul>\n<li><strong>Definition:</strong> A gap between the expected and observed split of users across variants, signaling a flaw in the experiment.</li>\n<li><strong>Example:</strong> A planned 50/50 split that shows 52/48 across millions of users.</li>\n<li><strong>Non-example:</strong> A small imbalance expected in a tiny sample.</li>\n<li><strong>Owning chapter:</strong> C14</li>\n</ul>\n<span id=\"gl-sanity-check\"></span>\n<h3>sanity check</h3>\n<ul>\n<li><strong>Definition:</strong> Testing a result against an independent route or a known bound before trusting it.</li>\n<li><strong>Example:</strong> Comparing a bottom-up estimate of coffee shops with a per-capita figure.</li>\n<li><strong>Non-example:</strong> Re-running the same arithmetic.</li>\n<li><strong>Owning chapter:</strong> C04</li>\n</ul>\n<span id=\"gl-say-do-gap\"></span>\n<h3>say-do gap</h3>\n<ul>\n<li><strong>Definition:</strong> The difference between what people say they do or want and what they actually do.</li>\n<li><strong>Example:</strong> Users report reading settings pages; logs show few ever open them.</li>\n<li><strong>Non-example:</strong> A survey sample that over-represents one group.</li>\n<li><strong>Owning chapter:</strong> C06</li>\n</ul>\n<span id=\"gl-schema\"></span>\n<h3>schema</h3>\n<ul>\n<li><strong>Definition:</strong> The defined structure of stored data: the entities, their fields and how they relate.</li>\n<li><strong>Example:</strong> A users table, an orders table, and a rule that one order belongs to one user and has many items.</li>\n<li><strong>Non-example:</strong> A single free-text field holding everything about a customer.</li>\n<li><strong>Owning chapter:</strong> C21</li>\n</ul>\n<span id=\"gl-scope-creep\"></span>\n<h3>scope creep</h3>\n<ul>\n<li><strong>Definition:</strong> The growth of a project's scope after it starts, without a matching change in time, resources or other scope, which delays or degrades delivery.</li>\n<li><strong>Example:</strong> Ten stories become fourteen mid-project with the same date and the same three engineers.</li>\n<li><strong>Non-example:</strong> A deliberate, agreed change in scope with the trade named.</li>\n<li><strong>Owning chapter:</strong> C15</li>\n</ul>\n<span id=\"gl-scorecard\"></span>\n<h3>scorecard</h3>\n<ul>\n<li><strong>Definition:</strong> A one-page form listing the dimensions of an interview round, a score for each anchored to the bands, the evidence for each score and an overall lean.</li>\n<li><strong>Example:</strong> Five product-sense dimensions each scored 1 to 5 with the sentence said as evidence and a lean of hire.</li>\n<li><strong>Non-example:</strong> A general impression of how the answer went.</li>\n<li><strong>Owning chapter:</strong> C34</li>\n</ul>\n<span id=\"gl-seasonality\"></span>\n<h3>seasonality</h3>\n<ul>\n<li><strong>Definition:</strong> A regular, calendar-linked pattern in a metric (day of week, holidays, school terms, weather) that recurs and should be removed before inferring cause.</li>\n<li><strong>Example:</strong> A desktop-heavy dip in queries during a national holiday week that also appeared last year.</li>\n<li><strong>Non-example:</strong> A one-off drop caused by a release.</li>\n<li><strong>Owning chapter:</strong> C13</li>\n</ul>\n<span id=\"gl-second-order-effect\"></span>\n<h3>second-order effect</h3>\n<ul>\n<li><strong>Definition:</strong> A consequence of a consequence, usually produced by other people's response to the first change.</li>\n<li><strong>Example:</strong> A referral bonus raises signups, then attracts bonus-seekers who never become active and raise support costs.</li>\n<li><strong>Non-example:</strong> The direct, intended result of the change.</li>\n<li><strong>Owning chapter:</strong> C02</li>\n</ul>\n<span id=\"gl-sensitivity-analysis\"></span>\n<h3>sensitivity analysis</h3>\n<ul>\n<li><strong>Definition:</strong> Checking how much a result changes when one assumption changes, to find the assumption that matters most.</li>\n<li><strong>Example:</strong> Halving the weekly-ordering share halves the delivery estimate, while changing orders per household barely moves it.</li>\n<li><strong>Non-example:</strong> Running the same calculation again with the same inputs.</li>\n<li><strong>Owning chapter:</strong> C04</li>\n</ul>\n<span id=\"gl-service-level-objective\"></span>\n<h3>service level objective</h3>\n<ul>\n<li><strong>Definition:</strong> A target for a measured aspect of service quality over a period, such as 99.9% of requests succeeding monthly; the allowed shortfall is the error budget.</li>\n<li><strong>Example:</strong> 99.9% of payment attempts succeed each month, giving a budget of about 43.8 minutes of failure.</li>\n<li><strong>Non-example:</strong> A promise to customers with penalties, which is a service level agreement.</li>\n<li><strong>Owning chapter:</strong> C21</li>\n</ul>\n<span id=\"gl-shadow-mode\"></span>\n<h3>shadow mode</h3>\n<ul>\n<li><strong>Definition:</strong> A deployment in which a new system runs on live inputs and its outputs are logged and judged but not shown to users.</li>\n<li><strong>Example:</strong> A summarizer producing summaries for reviewers to score while users still see the original notifications.</li>\n<li><strong>Non-example:</strong> A canary release that users can see.</li>\n<li><strong>Owning chapter:</strong> C25</li>\n</ul>\n<span id=\"gl-signal\"></span>\n<h3>signal</h3>\n<ul>\n<li><strong>Definition:</strong> What an interviewer infers about your judgment, skills, values or growth from an answer; a story with a real decision, personal action, evidence and learning gives strong signal and a vague one gives none.</li>\n<li><strong>Example:</strong> A conflict story in which you asked what each step was for, ran a test and credited the colleague's idea.</li>\n<li><strong>Non-example:</strong> A story told entirely as 'we' with no decision and no number.</li>\n<li><strong>Owning chapter:</strong> C31</li>\n</ul>\n<span id=\"gl-simpsons-paradox\"></span>\n<h3>Simpson's paradox</h3>\n<ul>\n<li><strong>Definition:</strong> A pattern in which a trend appears in every subgroup but reverses or disappears when the groups are combined.</li>\n<li><strong>Example:</strong> A new flow improves conversion on both mobile and desktop, yet overall conversion falls because mobile share grew.</li>\n<li><strong>Non-example:</strong> A metric moving in one direction in every segment.</li>\n<li><strong>Owning chapter:</strong> C12</li>\n</ul>\n<span id=\"gl-smoke-test\"></span>\n<h3>smoke test</h3>\n<ul>\n<li><strong>Definition:</strong> A test of demand run before the product exists, by presenting the offer (a page, an advertisement, a button) and measuring whether people take a costly-enough action such as signing up, leaving a deposit or pre-ordering.</li>\n<li><strong>Example:</strong> A landing page with a price and a refundable $5 deposit shown to 700 target visitors.</li>\n<li><strong>Non-example:</strong> A usability test of a finished prototype, or asking friends whether they like the idea.</li>\n<li><strong>Owning chapter:</strong> C26</li>\n</ul>\n<span id=\"gl-sprint\"></span>\n<h3>sprint</h3>\n<ul>\n<li><strong>Definition:</strong> A fixed, short period (commonly one to two weeks) in which a team commits to a set of work and delivers it in a usable state.</li>\n<li><strong>Example:</strong> A two-week sprint to deliver the view-only share link and its tests.</li>\n<li><strong>Non-example:</strong> An open-ended project phase with no fixed end.</li>\n<li><strong>Owning chapter:</strong> C16</li>\n</ul>\n<span id=\"gl-sql\"></span>\n<h3>SQL</h3>\n<ul>\n<li><strong>Definition:</strong> Structured query language: the language most analytics databases use to read, filter and combine tables of data.</li>\n<li><strong>Example:</strong> A query that counts the orders placed each day, grouped by country.</li>\n<li><strong>Non-example:</strong> A spreadsheet formula.</li>\n<li><strong>Owning chapter:</strong> C13</li>\n</ul>\n<span id=\"gl-staged-rollout\"></span>\n<h3>staged rollout</h3>\n<ul>\n<li><strong>Definition:</strong> Releasing a change to progressively larger shares of users while monitoring for problems.</li>\n<li><strong>Example:</strong> 1%, then 10%, then 50%, then everyone, with checks between steps.</li>\n<li><strong>Non-example:</strong> Releasing to all users at once.</li>\n<li><strong>Owning chapter:</strong> C17</li>\n</ul>\n<span id=\"gl-stakeholder\"></span>\n<h3>stakeholder</h3>\n<ul>\n<li><strong>Definition:</strong> A person or group who affects or is affected by a decision or product and whose support, input or approval it needs.</li>\n<li><strong>Example:</strong> Privacy counsel, the growth lead, the engineering lead and the VP who decides.</li>\n<li><strong>Non-example:</strong> Only the people who attend the planning meeting.</li>\n<li><strong>Owning chapter:</strong> C32</li>\n</ul>\n<span id=\"gl-standard-error\"></span>\n<h3>standard error</h3>\n<ul>\n<li><strong>Definition:</strong> The standard deviation of an estimate across repeated samples, which shows how much the estimate would move if the sample were drawn again; it shrinks with the square root of the sample size.</li>\n<li><strong>Example:</strong> For a 4% rate measured on 10,000 users, about 0.2 percentage points.</li>\n<li><strong>Non-example:</strong> The spread of individual users' values, which is the standard deviation of the data.</li>\n<li><strong>Owning chapter:</strong> C12</li>\n</ul>\n<span id=\"gl-statistical-power\"></span>\n<h3>statistical power</h3>\n<ul>\n<li><strong>Definition:</strong> The probability that a test detects an effect of a given size when that effect really exists.</li>\n<li><strong>Example:</strong> A test with 80% power to detect a two-point lift.</li>\n<li><strong>Non-example:</strong> The share of users in the test.</li>\n<li><strong>Owning chapter:</strong> C12</li>\n</ul>\n<span id=\"gl-story-bank\"></span>\n<h3>story bank</h3>\n<ul>\n<li><strong>Definition:</strong> A prepared set of real experiences from your own work, each with notes, mapped to the themes interviewers ask about, from which you choose a story for each question.</li>\n<li><strong>Example:</strong> Nine rehearsed stories with verified numbers covering conflict, failure, influence, ambiguity, customer focus, a data decision, prioritization, leading and a values moment.</li>\n<li><strong>Non-example:</strong> A set of memorized scripts or stories invented to fit a company's list of values.</li>\n<li><strong>Owning chapter:</strong> C31</li>\n</ul>\n<span id=\"gl-strategy\"></span>\n<h3>strategy</h3>\n<ul>\n<li><strong>Definition:</strong> A coherent set of choices about where to compete and how to win, grounded in a diagnosis of the situation.</li>\n<li><strong>Example:</strong> Entering a market with a narrow wedge where the company has a distribution advantage.</li>\n<li><strong>Non-example:</strong> A list of goals with no choices about how to reach them.</li>\n<li><strong>Owning chapter:</strong> C18</li>\n</ul>\n<span id=\"gl-sunk-cost\"></span>\n<h3>sunk cost</h3>\n<ul>\n<li><strong>Definition:</strong> Cost already spent and not recoverable, which should not drive a forward-looking decision.</li>\n<li><strong>Example:</strong> The four months already spent on a feature, when deciding whether to spend three more.</li>\n<li><strong>Non-example:</strong> The remaining cost of finishing the project.</li>\n<li><strong>Owning chapter:</strong> C02</li>\n</ul>\n<span id=\"gl-survivorship-bias\"></span>\n<h3>survivorship bias</h3>\n<ul>\n<li><strong>Definition:</strong> Drawing conclusions from the items that remain after a selection process while ignoring those removed by it.</li>\n<li><strong>Example:</strong> Concluding that a feature drives retention because users who stayed a year all used it, when users who left early never had the chance.</li>\n<li><strong>Non-example:</strong> A retention analysis that follows every user from sign-up, including those who left.</li>\n<li><strong>Owning chapter:</strong> C12</li>\n</ul>\n<span id=\"gl-switching-cost\"></span>\n<h3>switching cost</h3>\n<ul>\n<li><strong>Definition:</strong> The cost, in money, time, effort or risk, a customer bears to change from one provider to another.</li>\n<li><strong>Example:</strong> Moving years of documents, habits and integrations to a different service.</li>\n<li><strong>Non-example:</strong> A cancellation fee that customers resent but can easily avoid by exporting.</li>\n<li><strong>Owning chapter:</strong> C18</li>\n</ul>\n<span id=\"gl-symptom\"></span>\n<h3>symptom</h3>\n<ul>\n<li><strong>Definition:</strong> An observable sign of a problem, which may be fixed in one instance without removing what produces it.</li>\n<li><strong>Example:</strong> Checkout conversion fell.</li>\n<li><strong>Non-example:</strong> A payment-library update that broke one step on older phones.</li>\n<li><strong>Owning chapter:</strong> C03</li>\n</ul>\n<span id=\"gl-take-rate\"></span>\n<h3>take rate</h3>\n<ul>\n<li><strong>Definition:</strong> The share of transaction value that a platform keeps.</li>\n<li><strong>Example:</strong> A platform keeping 20% of each sale.</li>\n<li><strong>Non-example:</strong> The share of visitors who convert.</li>\n<li><strong>Owning chapter:</strong> C19</li>\n</ul>\n<span id=\"gl-teardown\"></span>\n<h3>teardown</h3>\n<ul>\n<li><strong>Definition:</strong> A structured analysis of how a product works and why, covering design, strategy and economics, from public information and use.</li>\n<li><strong>Example:</strong> Walking a competitor's sign-up flow, noting its pricing and distribution from public sources, and labeling what is observed, inferred and unknown.</li>\n<li><strong>Non-example:</strong> A list of features copied from a rival, or claims about the rival's internal metrics.</li>\n<li><strong>Owning chapter:</strong> C11</li>\n</ul>\n<span id=\"gl-technical-debt\"></span>\n<h3>technical debt</h3>\n<ul>\n<li><strong>Definition:</strong> The accumulated cost of earlier shortcuts or aging design choices in a system, which makes later changes slower or riskier; the principal is the work to fix it and the interest is the extra cost paid each time the team works around it.</li>\n<li><strong>Example:</strong> A fragile billing module that costs 15% of a team's capacity in workarounds each sprint.</li>\n<li><strong>Non-example:</strong> A feature the team has not built yet.</li>\n<li><strong>Owning chapter:</strong> C16</li>\n</ul>\n<span id=\"gl-threshold\"></span>\n<h3>threshold</h3>\n<ul>\n<li><strong>Definition:</strong> The score above which a classifier's output triggers an action; moving it trades one kind of error for the other.</li>\n<li><strong>Example:</strong> Flag every item scoring above 0.7.</li>\n<li><strong>Non-example:</strong> The model's score itself.</li>\n<li><strong>Owning chapter:</strong> C23</li>\n</ul>\n<span id=\"gl-throughput\"></span>\n<h3>throughput</h3>\n<ul>\n<li><strong>Definition:</strong> The amount of work a system completes per unit of time, such as requests per second; it is distinct from latency.</li>\n<li><strong>Example:</strong> A service handling 20,000 requests per second.</li>\n<li><strong>Non-example:</strong> How long one request takes.</li>\n<li><strong>Owning chapter:</strong> C21</li>\n</ul>\n<span id=\"gl-time-box\"></span>\n<h3>time-box</h3>\n<ul>\n<li><strong>Definition:</strong> A fixed period given to a piece of work, with scope that flexes to fit.</li>\n<li><strong>Example:</strong> Two weeks to build the best first slice of a feature, then reassess.</li>\n<li><strong>Non-example:</strong> An open-ended task with a fixed scope and no date.</li>\n<li><strong>Owning chapter:</strong> C15</li>\n</ul>\n<span id=\"gl-token\"></span>\n<h3>token</h3>\n<ul>\n<li><strong>Definition:</strong> A chunk of text, often a word or part of a word, that a language model reads and writes; models are priced, limited and slowed by tokens.</li>\n<li><strong>Example:</strong> About 1,000 tokens is roughly 750 English words.</li>\n<li><strong>Non-example:</strong> A security token used to log in.</li>\n<li><strong>Owning chapter:</strong> C24</li>\n</ul>\n<span id=\"gl-total-addressable-market\"></span>\n<h3>total addressable market</h3>\n<ul>\n<li><strong>Definition:</strong> The total revenue available if every potential customer bought the product; narrower layers (serviceable and obtainable market) are the usable ones for planning.</li>\n<li><strong>Example:</strong> A $60 million ceiling for pet telemedicine in three to five years, of which an entrant might obtain 10%.</li>\n<li><strong>Non-example:</strong> One percent of a multi-trillion-dollar industry used as a market size.</li>\n<li><strong>Owning chapter:</strong> C18</li>\n</ul>\n<span id=\"gl-tradeoff\"></span>\n<h3>tradeoff</h3>\n<ul>\n<li><strong>Definition:</strong> A choice in which gaining on one dimension costs something on another, stated with what is given up.</li>\n<li><strong>Example:</strong> Shipping two weeks sooner by cutting the search filters from the first release.</li>\n<li><strong>Non-example:</strong> Calling one option &quot;best&quot; without naming its cost.</li>\n<li><strong>Owning chapter:</strong> C02</li>\n</ul>\n<span id=\"gl-training-data\"></span>\n<h3>training data</h3>\n<ul>\n<li><strong>Definition:</strong> The set of past examples a model learns from.</li>\n<li><strong>Example:</strong> Millions of past payments with the outcome of whether each was later disputed.</li>\n<li><strong>Non-example:</strong> The new cases the model will be used on.</li>\n<li><strong>Owning chapter:</strong> C23</li>\n</ul>\n<span id=\"gl-trust-and-safety\"></span>\n<h3>trust and safety</h3>\n<ul>\n<li><strong>Definition:</strong> The work of protecting users and a platform from abuse, fraud, harassment, harmful content and manipulation through policy, product design, detection and enforcement, against adversaries who adapt.</li>\n<li><strong>Example:</strong> Designing layers of prevention, detection, review and appeals for a live-video feature.</li>\n<li><strong>Non-example:</strong> A report button with no policy, detection or appeals behind it.</li>\n<li><strong>Owning chapter:</strong> C27</li>\n</ul>\n<span id=\"gl-trust-signal\"></span>\n<h3>trust signal</h3>\n<ul>\n<li><strong>Definition:</strong> A visible cue that tells a person a product, a person or a payment is legitimate and safe, whose absence can stop a transaction.</li>\n<li><strong>Example:</strong> A cash agent who is a shopkeeper the customer already knows, or a receipt in the local language.</li>\n<li><strong>Non-example:</strong> A security badge nobody recognizes.</li>\n<li><strong>Owning chapter:</strong> C09</li>\n</ul>\n<span id=\"gl-two-sided-market\"></span>\n<h3>two-sided market</h3>\n<ul>\n<li><strong>Definition:</strong> A market with two distinct groups of participants who need each other, where the platform's value to each group depends on the size and quality of the other.</li>\n<li><strong>Example:</strong> Riders and drivers; buyers and sellers.</li>\n<li><strong>Non-example:</strong> A product with many users who do not interact with one another.</li>\n<li><strong>Owning chapter:</strong> C19</li>\n</ul>\n<span id=\"gl-underserved-user\"></span>\n<h3>underserved user</h3>\n<ul>\n<li><strong>Definition:</strong> A person or group that existing products fail because of cost, access, ability or context, described by what the product lacks for them and not by who they are.</li>\n<li><strong>Example:</strong> Adults in a rural district with a shared basic phone and no internet, who live far from a clinic.</li>\n<li><strong>Non-example:</strong> &quot;The poor,&quot; which is a label and gives no design direction.</li>\n<li><strong>Owning chapter:</strong> C09</li>\n</ul>\n<span id=\"gl-unit-economics\"></span>\n<h3>unit economics</h3>\n<ul>\n<li><strong>Definition:</strong> The revenue and cost attached to a single unit, such as a customer or an order, showing whether each unit makes money.</li>\n<li><strong>Example:</strong> Average revenue per order minus delivery, payment and support cost per order.</li>\n<li><strong>Non-example:</strong> Total company profit.</li>\n<li><strong>Owning chapter:</strong> C18</li>\n</ul>\n<span id=\"gl-usability-heuristic\"></span>\n<h3>usability heuristic</h3>\n<ul>\n<li><strong>Definition:</strong> A rule of thumb for judging whether an interface is easy to use, applied by an evaluator without users.</li>\n<li><strong>Example:</strong> Checking that every error message says what went wrong and what to do next.</li>\n<li><strong>Non-example:</strong> A usability test, which watches real users attempt tasks.</li>\n<li><strong>Owning chapter:</strong> C10</li>\n</ul>\n<span id=\"gl-user-segment\"></span>\n<h3>user segment</h3>\n<ul>\n<li><strong>Definition:</strong> A group of users defined by shared needs or behavior that matter to the decision at hand.</li>\n<li><strong>Example:</strong> Weekly commuters who change routes often.</li>\n<li><strong>Non-example:</strong> &quot;Women&quot;, with no link to a need or behavior.</li>\n<li><strong>Owning chapter:</strong> C06</li>\n</ul>\n<span id=\"gl-user-story\"></span>\n<h3>user story</h3>\n<ul>\n<li><strong>Definition:</strong> A short description of a capability from the user's point of view, usually in the form 'As a [user], I want [capability] so that [benefit].'</li>\n<li><strong>Example:</strong> As a shopper planning a trip with a friend, I want to share my packing list so that my friend can tick things off.</li>\n<li><strong>Non-example:</strong> 'Add a share button,' which names a control and no purpose.</li>\n<li><strong>Owning chapter:</strong> C16</li>\n</ul>\n<span id=\"gl-value-metric\"></span>\n<h3>value metric</h3>\n<ul>\n<li><strong>Definition:</strong> The unit on which price is charged, such as seats, tasks, storage, transactions or outcomes, chosen so that price grows as the customer's value grows and as the seller's cost grows.</li>\n<li><strong>Example:</strong> A per-seat price with an included allowance of tasks and a per-task overage.</li>\n<li><strong>Non-example:</strong> A flat price unrelated to use.</li>\n<li><strong>Owning chapter:</strong> C20</li>\n</ul>\n<span id=\"gl-vanity-metric\"></span>\n<h3>vanity metric</h3>\n<ul>\n<li><strong>Definition:</strong> A number that rises reliably and flatters but does not tell you whether the product is working or what to do; a test is whether any decision would change if it fell.</li>\n<li><strong>Example:</strong> Registered users, which only ever grows.</li>\n<li><strong>Non-example:</strong> Weekly active users who return in each of four consecutive weeks, by cohort, with a guardrail.</li>\n<li><strong>Owning chapter:</strong> C29</li>\n</ul>\n<span id=\"gl-webhook\"></span>\n<h3>webhook</h3>\n<ul>\n<li><strong>Definition:</strong> A message one system sends to another's web address when an event happens, so the receiver need not keep asking.</li>\n<li><strong>Example:</strong> A payments service telling a merchant's server that a payment succeeded.</li>\n<li><strong>Non-example:</strong> A merchant polling every minute to ask whether anything changed.</li>\n<li><strong>Owning chapter:</strong> C22</li>\n</ul>\n<span id=\"gl-willingness-to-pay\"></span>\n<h3>willingness to pay</h3>\n<ul>\n<li><strong>Definition:</strong> The most a customer is prepared to pay for something, which varies by customer and by what they compare it with.</li>\n<li><strong>Example:</strong> A survey in which 41% of target customers say they would buy at $449.</li>\n<li><strong>Non-example:</strong> The cost of producing the product.</li>\n<li><strong>Owning chapter:</strong> C20</li>\n</ul>\n<span id=\"appendix-a\"></span>\n";
